package jp.tapmarker;
import java.util.*;
public final class ContinuousRecoveryTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{
  Map<String,float[]> refs=VirtualPresetProfileTest.canonical("tests/usagi-replay.bin");PhaseEngine e=new PhaseEngine();UsagiPreset.install(e,refs);e.strictRuntime=true;e.enter(UsagiPreset.PREFIX+"mission-tap",0);MissionJourney journey=new MissionJourney();journey.route(UsagiPreset.PREFIX+"clear");journey.route(e.current);RecoveryBudget mission=new RecoveryBudget(4);
  PhaseEngine.Watch tap=e.rule(UsagiPreset.PREFIX+"ミッション中央をタップ");Map<String,float[]> button=new HashMap<>();button.put(tap.regionId,tap.reference.clone());
  for(int i=0;i<4;i++){long time=100+i*300;e.observe(button,time);check(e.poll()==null,"new mission image needs two frames");e.observe(button,time+120);PhaseEngine.Watch w=e.poll();check(w==tap&&mission.acquire(time+120),"four mission attempts allowed");check(e.cancelIfCurrent(w,e.current,e.epoch),"incomplete attempt releases rule");check(e.current.equals(UsagiPreset.PREFIX+"mission-tap"),"failed input does not pretend mission transition completed");}
  e.observe(button,2000);e.observe(button,2120);PhaseEngine.Watch waiting=e.poll();check(waiting==tap&&!mission.acquire(2120),"retry exhaustion holds input");String state=e.current;long epoch=e.epoch;check(e.cancelIfCurrent(waiting,state,epoch),"held action can be observed again");check(journey.blocksMain(),"incomplete mission still blocks main-loop tapping");
  Map<String,float[]> opened=new HashMap<>();PhaseEngine.Watch visible=e.rule(UsagiPreset.PREFIX+"already-tapped-missions");opened.put(visible.regionId,visible.reference.clone());e.observe(opened,2240);check(e.poll()==null,"while waiting, actual transition is still confirmed");e.observe(opened,2360);PhaseEngine.Watch w=e.poll();check(w==visible,"mission screen can be recognized during retry cooldown");e.finish(w,2360);check(e.current.equals(UsagiPreset.PREFIX+"missions"),"observed screen resumes correct mission phase");check(!e.finishIfCurrent(tap,state,epoch,2400),"late input result cannot overwrite the newly observed mission state");
  check(mission.acquire(10120),"mission input recovers after cooldown");RecoveryBudget a=new RecoveryBudget(),b=new RecoveryBudget();for(int i=0;i<3;i++)check(a.acquire(i*6000),"restore attempt accepted");check(!a.acquire(18000)&&a.remaining(18120)==7880,"restore budget yields to observation");check(b.acquire(18120),"second display continues independently");a.reset();check(a.acquire(18121),"verified home permits immediate operation without waiting out old cooldown");
  e.enter(UsagiPreset.PREFIX+"unknown",0);e.observe(Collections.emptyMap(),1);w=e.poll();check(w!=null&&w.action==PhaseEngine.STOP,"configured explicit stop retains its behavior");
  System.out.println("ContinuousRecoveryTest: "+checks+" checks passed; failed/held input, observed mission transition, independent budgets and explicit stop");
 }
}
